-- Airport Manager database, part 4: Flights: the 96 flights of 2026-11-18 plus past and future trips.
-- Run order: 4 of 6
-- Requires files 01 to 03 already executed.
-- Open it in MySQL Workbench and click the lightning bolt, or run: mysql -u root -p < 04_flights.sql

SET NAMES utf8mb4;
USE airport_manager;

-- Flights: ids 1 to 96 are the 96 flights of 2026-11-18 (58 departures, 38 arrivals); the next ones are past and future trips

-- Expected counts: flights = 117
SELECT 'flights' AS table_name, COUNT(*) AS total FROM flights;
